/**
 * @description Shares each outbound transaction Read Only with the users and groups its related record is shared with
 * (sharing reason Related Record Access), when the event has Share With Related Record on.
 * @group Integration Hub
 */
public with sharing class IntegrationHubSharing {

    /**
     * @description Copies the related records' share rows to new transactions.
     * @param txns the transactions (Id, Event__c, Related_Record_Id__c, Related_Object__c, OwnerId)
     */
    public static void copyShares(List<IH_Transaction__c> txns) {
        List<IH_Transaction__c> eligible = eligible(txns);
        Map<String, Set<Id>> idsByObject = new Map<String, Set<Id>>();
        for (IH_Transaction__c t : eligible) {
            if (!idsByObject.containsKey(t.Related_Object__c)) {
                idsByObject.put(t.Related_Object__c, new Set<Id>());
            }
            idsByObject.get(t.Related_Object__c).add((Id) t.Related_Record_Id__c);
        }
        Map<Id, Set<Id>> sharedWith = new Map<Id, Set<Id>>();
        for (String objectName : idsByObject.keySet()) {
            sharedWith.putAll(shareRows(objectName, idsByObject.get(objectName)));
        }
        List<IH_Transaction__Share> shares = new List<IH_Transaction__Share>();
        for (IH_Transaction__c t : eligible) {
            for (Id who : sharedWith.containsKey((Id) t.Related_Record_Id__c) ? sharedWith.get((Id) t.Related_Record_Id__c) : new Set<Id>()) {
                if (who != t.OwnerId) {
                    shares.add(new IH_Transaction__Share(ParentId = t.Id, UserOrGroupId = who, AccessLevel = 'Read',
                        RowCause = Schema.IH_Transaction__Share.RowCause.Related_Record_Access__c));
                }
            }
        }
        IntegrationHubData.insertEach(shares);
    }

    /**
     * @description Removes and copies again the shares of these related records' transactions.
     * @param relatedRecordIds the related record Ids
     */
    public static void resync(Set<Id> relatedRecordIds) {
        if (relatedRecordIds == null || relatedRecordIds.isEmpty()) {
            return;
        }
        Set<String> keys = new Set<String>();
        for (Id rid : relatedRecordIds) {
            keys.add(String.valueOf(rid));
        }
        List<IH_Transaction__c> txns = (List<IH_Transaction__c>) IntegrationHubData.query(
            'SELECT Id, OwnerId, Event__c, Related_Record_Id__c, Related_Object__c FROM IH_Transaction__c '
            + 'WHERE Related_Record_Id__c IN :keys LIMIT 10000', new Map<String, Object>{ 'keys' => keys });
        IntegrationHubData.deleteEach(IntegrationHubData.query(
            'SELECT Id FROM IH_Transaction__Share WHERE ParentId IN :ids AND RowCause = :cause',
            new Map<String, Object>{ 'ids' => new Map<Id, IH_Transaction__c>(txns).keySet(), 'cause' => Schema.IH_Transaction__Share.RowCause.Related_Record_Access__c }));
        copyShares(txns);
    }

    private static List<IH_Transaction__c> eligible(List<IH_Transaction__c> txns) {
        Set<Id> eventIds = new Set<Id>();
        for (IH_Transaction__c t : txns) {
            eventIds.add(t.Event__c);
        }
        Set<Id> sharedEvents = new Map<Id, SObject>(IntegrationHubData.query(
            'SELECT Id FROM IH_Event__c WHERE Id IN :ids AND Share_With_Related_Record__c = true',
            new Map<String, Object>{ 'ids' => eventIds })).keySet();
        List<IH_Transaction__c> result = new List<IH_Transaction__c>();
        for (IH_Transaction__c t : txns) {
            if (sharedEvents.contains(t.Event__c) && String.isNotBlank(t.Related_Record_Id__c) && String.isNotBlank(t.Related_Object__c)) {
                result.add(t);
            }
        }
        return result;
    }

    private static Map<Id, Set<Id>> shareRows(String objectName, Set<Id> ids) {
        Map<Id, Set<Id>> result = new Map<Id, Set<Id>>();
        String shareObject = shareObjectName(objectName);
        String parentField = shareParentField(objectName);
        Schema.SObjectType shareType = Schema.getGlobalDescribe().get(shareObject);
        if (shareType == null || !shareType.getDescribe(SObjectDescribeOptions.DEFERRED).fields.getMap().containsKey(parentField)) {
            return result;
        }
        String soql = 'SELECT ' + String.escapeSingleQuotes(parentField) + ', UserOrGroupId FROM ' + String.escapeSingleQuotes(shareObject)
            + ' WHERE ' + String.escapeSingleQuotes(parentField) + ' IN :ids';
        for (SObject row : IntegrationHubData.query(soql, new Map<String, Object>{ 'ids' => ids })) {
            Id parentId = (Id) row.get(parentField);
            if (!result.containsKey(parentId)) {
                result.put(parentId, new Set<Id>());
            }
            result.get(parentId).add((Id) row.get('UserOrGroupId'));
        }
        return result;
    }

    /**
     * @description The share object of an object: Foo__c gives Foo__Share, Account gives AccountShare.
     * @param objectName the object API name
     * @return the share object API name
     */
    @TestVisible
    private static String shareObjectName(String objectName) {
        return objectName.endsWithIgnoreCase('__c') ? objectName.removeEndIgnoreCase('__c') + '__Share' : objectName + 'Share';
    }

    /**
     * @description The parent field of a share object: ParentId for custom objects, AccountId for Account.
     * @param objectName the object API name
     * @return the parent field name
     */
    @TestVisible
    private static String shareParentField(String objectName) {
        return objectName.endsWithIgnoreCase('__c') ? 'ParentId' : objectName + 'Id';
    }
}
